41	    let ctx = DeviceContext::new().unwrap();
42	    let values: Vec<bf16> = (0..4u16)
43	        .map(|i| bf16::from_f32(f32::from(i) + 0.5))
44	        .collect();
45	    let payload: Vec<u8> = values
46	        .iter()
47	        .flat_map(|v| v.to_bits().to_le_bytes())
48	        .collect();
49	    let view = TensorView::new(Dtype::BF16, vec![4], &payload).unwrap();
50	    let bytes = safetensors::serialize([("v".to_string(), view)], None).unwrap();
51	
52	    // Stage the archive at both parities and keep the one whose payload
53	    // pointer is odd, forcing the owned-decode path.
54	    let mut backing = vec![0u8; bytes.len() + 1];
55	    let mut chosen = None;
56	    for start in [0usize, 1] {
57	        backing[start..start + bytes.len()].copy_from_slice(&bytes);
58	        let shard = SafeTensors::deserialize(&backing[start..start + bytes.len()]).unwrap();
59	        if shard.tensor("v").unwrap().data().as_ptr() as usize % 2 == 1 {
60	            chosen = Some(start);
61	            break;
62	        }
63	    }
64	    let start = chosen.expect("adjacent offsets have opposite payload parity");
65	    let shards = vec![SafeTensors::deserialize(&backing[start..start + bytes.len()]).unwrap()];
66	    let weight_map = HashMap::new();
67	
68	    let mut loader = StagedWeightLoader::new(&ctx, &shards, &weight_map).unwrap();
69	    let slot = loader.vector("v", 4).unwrap();
70	    loader.finish().unwrap();
71	
72	    let out = loader.take_vec(slot);
73	    let host: Vec<bf16> = ctx.stream.clone_dtoh(&out.data).unwrap();
74	    let got: Vec<u16> = host.iter().map(|v| v.to_bits()).collect();
75	    let want: Vec<u16> = values.iter().map(|v| v.to_bits()).collect();
76	    assert_eq!(got, want);
77	}
