use std::sync::Arc;

use anyhow::Result;
use anyhow::bail;
use cudarc::driver::CudaSlice;
use half::bf16;
pub use pegainfer_kernels::paged_kv::KvFormat;
pub use pegainfer_kernels::paged_kv::KvStorage;

use crate::page_pool::OwnedPagePermit;
use crate::page_pool::PageId;
use crate::page_pool::PagePool;
use crate::tensor::DeviceContext;

/// Page-first geometry: dimensions and derived strides for one page.
///
/// Pure value type — no GPU, no allocation. Shared by `KvPool`, `KvState`, `KvDesc`.
#[derive(Clone, Copy, Debug)]
pub struct KvLayout {
    pub page_size: usize,
    pub num_layers: usize,
    pub num_kv_heads: usize,
    pub head_dim: usize,
    /// Elements in one K (or V) block: page_size × num_kv_heads × head_dim.
    pub kv_block_len: usize,
    /// Elements between layers within a page: the format's values per token
    /// over the page's tokens and heads (K then V for `KvFormat::Split`).
    pub layer_stride: usize,
    /// Elements per page (all layers): num_layers × layer_stride.
    pub page_stride: usize,
    pub storage: KvStorage,
    pub format: KvFormat,
}

impl KvLayout {
    pub fn new(
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        page_size: usize,
    ) -> anyhow::Result<Self> {
        Self::with_storage(
            num_layers,
            num_kv_heads,
            head_dim,
            page_size,
            KvStorage::Bf16,
        )
    }

    pub fn with_storage(
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        page_size: usize,
        storage: KvStorage,
    ) -> anyhow::Result<Self> {
        Self::with_storage_and_format(
            num_layers,
            num_kv_heads,
            head_dim,
            page_size,
            storage,
            KvFormat::Split,
        )
    }

    pub fn with_storage_and_format(
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        page_size: usize,
        storage: KvStorage,
        format: KvFormat,
    ) -> anyhow::Result<Self> {
        let (kv_block_len, layer_stride, page_stride) = pegainfer_kernels::paged_kv::derive_strides(
            page_size,
            num_kv_heads,
            head_dim,
            num_layers,
            format,
        )
        .ok_or_else(|| {
            anyhow::anyhow!(
                "kv layout strides overflow usize or {format:?} does not fit head_dim {head_dim}: \
                 {num_layers} layers x {num_kv_heads} heads x {page_size} page"
            )
        })?;
        Ok(Self {
            page_size,
            num_layers,
            num_kv_heads,
            head_dim,
            kv_block_len,
            layer_stride,
            page_stride,
            storage,
            format,
        })
    }

    pub fn kernel_layout(&self) -> pegainfer_kernels::paged_kv::PagedKvLayout {
        pegainfer_kernels::paged_kv::PagedKvLayout {
            page_size: self.page_size,
            num_layers: self.num_layers,
            num_kv_heads: self.num_kv_heads,
            head_dim: self.head_dim,
            kv_block_len: self.kv_block_len,
            layer_stride: self.layer_stride,
            page_stride: self.page_stride,
            storage: self.storage,
            format: self.format,
        }
    }
}

struct KvPoolInner {
    pool: PagePool,
    buffer: CudaSlice<bf16>,
    layout: KvLayout,
    /// Reserved page for bucket CUDA Graph padding. FlashInfer metadata for
    /// padding slots points here with seq_len=1. KV append writes harmless
    /// garbage; attention output is discarded.
    padding_permit: OwnedPagePermit,
}

/// Shared KV backing storage with page-based allocation.
///
/// Owns a single GPU buffer in page-first layout: each page is a contiguous
/// chunk holding all layers' K and V for `page_size` tokens.
///
/// ```text
/// page_i: [L0_K | L0_V | L1_K | L1_V | ... | Ln_K | Ln_V]
///          └─ page_size × num_kv_heads × head_dim each ─┘
/// ```
///
/// Cheaply cloneable (Arc). Multiple `KvState`s share the same pool.
#[derive(Clone)]
pub struct KvPool {
    inner: Arc<KvPoolInner>,
}

impl KvPool {
    pub fn new(
        ctx: &DeviceContext,
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        page_size: usize,
        num_pages: usize,
    ) -> Result<Self> {
        Self::with_storage(
            ctx,
            num_layers,
            num_kv_heads,
            head_dim,
            page_size,
            num_pages,
            KvStorage::Bf16,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn with_storage(
        ctx: &DeviceContext,
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        page_size: usize,
        num_pages: usize,
        storage: KvStorage,
    ) -> Result<Self> {
        Self::with_storage_and_format(
            ctx,
            num_layers,
            num_kv_heads,
            head_dim,
            page_size,
            num_pages,
            storage,
            KvFormat::Split,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn with_storage_and_format(
        ctx: &DeviceContext,
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        page_size: usize,
        num_pages: usize,
        storage: KvStorage,
        format: KvFormat,
    ) -> Result<Self> {
        let layout = KvLayout::with_storage_and_format(
            num_layers,
            num_kv_heads,
            head_dim,
